}): Promise<CallToolResult>; };
```"}

{"name":"mcp__codex_apps__linear_list_comments","description":"Plan and build products

List comments on a Linear issue, project, initiative, document, project milestone, or project/initiative status update. Provide exactly one of `issueId`, `projectId`, `initiativeId`, `documentId`, `milestoneId`, or `statusUpdateId`. For issues, projects, and initiatives this returns both top-level discussion threads and inline description comments. Inline (anchored) comments carry a non-null `quotedText` set to the snippet of description text they reference. Returned comments include `author` and nullable `onBehalfOf`; when set, `onBehalfOf` identifies the user the agent author acted for. This tool is part of plugin `Linear`.

exec tool declaration:
```ts
declare const tools: { mcp__codex_apps__linear_list_comments(args: {
  // Next page cursor
  cursor?: string;
  // Document ID or slug (provide exactly one parent)
  documentId?: string;
  // Initiative name, ID, identifier (e.g., INIT-123), or slug (provide exactly one parent)
  initiativeId?: string;
  // Issue ID or identifier (e.g., LIN-123) (provide exactly one parent)
  issueId?: string;
  // Max results (default 50, max 250)
  limit?: number;
  // Milestone UUID (provide exactly one parent). Resolve milestone names via `list_milestones` first.
  milestoneId?: string;
  // Sort: createdAt | updatedAt
  orderBy?: "createdAt" | "updatedAt";
  // Project name, ID, identifier (e.g., PROJ-123), or slug (provide exactly one parent)
  projectId?: string;
  // Status update UUID (provide exactly one parent). Resolve status updates via `get_status_updates` first.
  statusUpdateId?: string;
  // Type of status update named by `statusUpdateId`, as returned by `get_status_updates`. Only valid together with `statusUpdateId`; omit to check both project and initiative status updates.
  statusUpdateType?: "project" | "initiative";
}): Promise<CallToolResult>; };
```"}

