};

const layerExportNamePattern = /(?:Live|Mock|Test|TestLive)$/u;

const noLayerExportsInServiceFiles = {
  create(context) {
    const reportName = (node) => {
      if (
        node?.type === "Identifier" &&
        layerExportNamePattern.test(node.name)
