      const [fixture, ...rest] = remaining;
      if (fixture === undefined) {
        return;
      }
      await runFixture(fixture);
      await runFixtures(rest);
    };

    await runFixtures(fixtures);
  }, 300_000);
});
import * as BunRuntime from "@effect/platform-bun/BunRuntime";
