      identifiers,
      loaderVariable: restoreInput.loaderVariable,
      report,
      reportedForwardingNodes,
      restoreCall,
      resultDeclarator,
      resultVariable,
    });
  }

  for (const restoreCalls of callsByConsumer.values()) {
