      )
    );
  }
  if (
    !paths.has(policy.fumadocs.source.path) ||
    !paths.has(policy.fumadocs.build.path)
  ) {
    result.push(
      diagnostic(
        "generated-source-owner",
        policy.fumadocs.source.owner,
        policy.fumadocs.generatedRoot,
