  target !== undefined &&
  target.length > 0 &&
  !target.startsWith("/") &&
  !target.startsWith("#") &&
  !/^[a-z][a-z0-9+.-]*:/iu.test(target) &&
  !paths.has(relativeTarget(sourcePath, target));

