  const result: DocumentationDiagnostic[] = [];
  const prose = file.text
    .replaceAll(/```[\s\S]*?```/gu, "")
    .replaceAll(/`[^`]*`/gu, "");
  for (const match of prose.matchAll(markdownLink)) {
    const matchedTarget = match.groups?.["target"];
    const target = matchedTarget?.split("#")[0];
