write({}, { value: 1 });
setValue({}, "value", 1);`,
  },
  {
    count: 1,
    name: "follows an assigned object-write alias",
    rule: "taxkit(no-object-writes)",
    source: `let write;
write = Reflect.set;
write({}, "value", 1);`,
  },
  {
    count: 0,
    name: "keeps a same-named local Object separate",
