      )
    )(result.stdout);
    expect(report.number_of_files).toBe(1);
    expect(Array.filter(report.diagnostics, (finding) => finding.code === rule)).toHaveLength(count);
    expect(Array.some(report.diagnostics, (finding) => finding.code.includes("plugin"))).toBe(false);
    if (name === "accepts persistent collections and Effect-managed immutable state") {
