    const acceptanceRecords = HashMap.fromIterable(
      Array.flatten(
        yield* Effect.forEach(
          ownerPolicy.public.statusDecision.acceptanceRecords,
          (binding) => {
            return Array.findFirst(
              files,
              (file) => file.path === binding.record
            ).pipe(
              Option.match({
                onNone: () => Effect.succeed([]),
                onSome: (recordFile) =>
                  decodePublicPageAcceptanceRecord(recordFile.text).pipe(
                    Effect.match({
                      onFailure: () => [],
                      onSuccess: (record) => [
                        [binding.record, record] as const,
                      ],
                    })
                  ),
              })
            );
          }
        )
      )
    );
    const manifests = yield* Effect.forEach(
      Array.filter(inventory, (entry) =>
        /^(?:apps|packages)\/.+\/package\.json$/u.test(entry)
      ),
      (manifestPath) =>
        fileSystem.readFileString(path.join(repositoryRoot, manifestPath)).pipe(
          Effect.flatMap(
            Schema.decodeUnknownEffect(
              Schema.fromJsonString(WorkspacePackageManifest)
            )
          ),
          Effect.map((manifest) => {
            const packageSummary = {
              scripts: HashSet.fromIterable(
                Record.keys(manifest.scripts ?? {})
              ),
            };
            const ownedPackageSummary = manifest.name
              ? { ...packageSummary, name: manifest.name }
              : packageSummary;

            return [
              manifestPath.replace(/\/package\.json$/u, ""),
              ownedPackageSummary,
            ] as const;
          }),
          Effect.mapError(
            () =>
              new DocumentationCheckError({
                operation: "decode-workspace-package-manifest",
              })
          )
        ),
      { concurrency: 8 }
    );
    const rootManifest = yield* fileSystem
      .readFileString(path.join(repositoryRoot, "package.json"))
      .pipe(
        Effect.flatMap(
          Schema.decodeUnknownEffect(
            Schema.fromJsonString(WorkspacePackageManifest)
          )
        ),
        Effect.mapError(
          () =>
            new DocumentationCheckError({
              operation: "decode-root-package-manifest",
            })
        )
      );
    return inspectDocumentation({
      acceptanceRecords,
      files,
      ownerPolicy,
      rootScripts: HashSet.fromIterable(
        Record.keys(rootManifest.scripts ?? {})
      ),
      workspaceScripts: HashMap.fromIterable(manifests),
    });
  }).pipe(Effect.scoped);

const program = (json: boolean) =>
  Effect.gen(function* documentationMain() {
    const fileSystem = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const root = yield* path.fromFileUrl(repositoryRootUrl).pipe(
      Effect.mapError(
        () =>
          new DocumentationCheckError({
            operation: "resolve-repository-root",
          })
      )
    );
    const report = yield* checkDocumentation(root);
    const receipt = receiptFor(report);
    const fullReport = yield* encodeReceipt(
      new DocumentationReceipt({
        ...receipt,
        diagnostics: report.diagnostics,
        omittedDiagnostics: 0,
      })
    );
    yield* fileSystem
      .makeDirectory(path.join(root, "tmp"), { recursive: true })
      .pipe(
        Effect.mapError(
          () =>
            new DocumentationCheckError({
              operation: "create-report-directory",
            })
        )
      );
    yield* fileSystem
      .writeFileString(path.join(root, reportPath), fullReport)
      .pipe(
        Effect.mapError(
          () => new DocumentationCheckError({ operation: "write-full-report" })
        )
      );
    const output = json ? yield* encodeReceipt(receipt) : renderHuman(receipt);
    yield* Console.info(output);
    return yield* receipt.ok
      ? Effect.void
      : Effect.fail(
          new DocumentationCheckError({
            operation: "documentation-policy-violations",
          })
        );
  }).pipe(Effect.scoped);

const command = Command.make(
  "check-docs",
  { json: Flag.Boolean("json") },
  ({ json }) => program(json)
);

Match.value(import.meta.main).pipe(
  Match.when(true, () =>
    BunRuntime.runMain(
      Command.run(command, {
        version: "repository-local",
        renderErrors: false,
      }).pipe(
        Effect.tapError(() =>
          Console.error(
            "Documentation check could not complete; repair the named repository-local policy or command options and rerun bun run check:docs."
          )
        ),
        Effect.provide(BunServices.layer)
      ),
      { disableErrorReporting: true }
    )
  ),
  Match.orElse(() => false)
);
import * as BunServices from "@effect/platform-bun/BunServices";
import { describe, expect, it as test } from "@effect/vitest";
import { Effect, Path, Schema, Stream } from "effect";
import { ChildProcess, ChildProcessSpawner } from "effect/process";

describe("runbook validator terminal output", () => {
  test.effect(
    "keeps a pre-receipt boundary failure bounded and free of home paths",
    () =>
      Effect.gen(function* () {
        const path = yield* Path.Path;
        const spawner = yield* ChildProcessSpawner.ChildProcessSpawner;
        const missingFixture = new URL(
          "../../../private-runbook-fixture/",
          import.meta.url
        );
        const encodedUrl = yield* Schema.encodeEffect(
          Schema.fromJsonString(Schema.String)
        )(missingFixture.href);
        const child = yield* spawner.spawn(
          ChildProcess.make(
            "bun",
            [
              "--conditions=source",
              "--eval",
              [
                'import * as BunRuntime from "@effect/platform-bun/BunRuntime";',
                'import * as BunServices from "@effect/platform-bun/BunServices";',
                'import { Effect } from "effect";',
                'import { runbookValidationOutcome } from "./tools/documentation/runbook-check.runtime.ts";',
                'import { RunbookValidationError } from "./tools/documentation/schemas.ts";',
                `const outcome = runbookValidationOutcome(new URL(${encodedUrl}));`,
                'BunRuntime.runMain(outcome.pipe(Effect.flatMap((ok) => ok ? Effect.void : Effect.fail(new RunbookValidationError({ operation: "fixture-result" }))), Effect.provide(BunServices.layer)), { disableErrorReporting: true });',
              ].join("\n"),
            ],
            {
              cwd: yield* path.fromFileUrl(new URL("../..", import.meta.url)),
              extendEnv: true,
              stderr: "pipe",
              stdout: "pipe",
              stdin: "ignore",
            }
          )
        );
        const [exitCode, output] = yield* Effect.all(
          [
            child.exitCode,
            Stream.mkString(Stream.decodeText(child.stderr)),
            Stream.runDrain(child.stdout),
          ],
          { concurrency: "unbounded" }
        );
        expect(Number(exitCode)).toBe(1);
        expect(output.length).toBeLessThan(1000);
        expect(output).toContain("operation=read-runbook-contract");
        expect(output).toContain("target=repository-local runbook contract");
        expect(output).toContain("recovery=");
        expect(output).toContain("nonclaim=");
        expect(output).not.toContain(missingFixture.pathname);
        expect(output).not.toMatch(/\/Users\/[^/\s]+\//u);
        expect(output).not.toContain("RunbookValidationError:");
      }).pipe(Effect.provide(BunServices.layer))
  );
});
"}

