import * as BunServices from "@effect/platform-bun/BunServices";
import { describe, expect, it as test } from "@effect/vitest";
import { Effect, Match, Result } from "effect";
import * as FileSystem from "effect/FileSystem";
import { ChildProcess, ChildProcessSpawner } from "effect/process";

import { checkRepositoryPaths } from "./check.runtime.js";
import { RepositoryRelativeFile } from "./schemas.js";

describe("repository path runtime", () => {
  test.effect(
    "maps a failed tracked-file inventory to a safe typed error",
    () =>
      Effect.gen(function* () {
        const result = yield* Effect.gen(function* inventoryFailure() {
          const fileSystem = yield* FileSystem.FileSystem;
          const directory = yield* fileSystem.makeTempDirectoryScoped({
            prefix: "taxkit-path-check-",
          });
          return yield* checkRepositoryPaths(directory).pipe(Effect.result);
        }).pipe(Effect.scoped, Effect.provide(BunServices.layer));
        Result.match(result, {
          onFailure: (error) =>
            Match.value(error).pipe(
              Match.tag("RepositoryInventoryError", (failure) => {
                expect(failure.operation).toBe("list-tracked-files");
              }),
              Match.orElse(() => expect.unreachable())
            ),
          onSuccess: () => expect.unreachable(),
        });
      })
  );
  test.effect(
    "maps an unreadable tracked file to its safe repository-relative location",
    () =>
      Effect.gen(function* () {
        const result = yield* Effect.gen(function* trackedFileReadFailure() {
          const childProcesses = yield* ChildProcessSpawner.ChildProcessSpawner;
          const fileSystem = yield* FileSystem.FileSystem;
          const directory = yield* fileSystem.makeTempDirectoryScoped({
            prefix: "taxkit-path-check-",
          });
          const trackedFile = "removed-after-index.md";
          yield* childProcesses
            .exitCode(
              ChildProcess.make("git", ["init", "--quiet"], {
                cwd: directory,
                stderr: "ignore",
                stdin: "ignore",
                stdout: "ignore",
              })
            )
            .pipe(
              Effect.flatMap((exitCode) =>
                Match.value(Number(exitCode)).pipe(
                  Match.when(0, () => Effect.void),
                  Match.orElse(() => Effect.die("git init failed"))
                )
              )
            );
          yield* fileSystem.writeFileString(
            `${directory}/${trackedFile}`,
            "portable text"
          );
          yield* childProcesses
            .exitCode(
              ChildProcess.make("git", ["add", "--", trackedFile], {
                cwd: directory,
                stderr: "ignore",
                stdin: "ignore",
                stdout: "ignore",
              })
            )
            .pipe(
              Effect.flatMap((exitCode) =>
                Match.value(Number(exitCode)).pipe(
                  Match.when(0, () => Effect.void),
                  Match.orElse(() => Effect.die("git add failed"))
                )
              )
            );
          yield* fileSystem.remove(`${directory}/${trackedFile}`);
          return yield* checkRepositoryPaths(directory).pipe(Effect.result);
        }).pipe(Effect.scoped, Effect.provide(BunServices.layer));
        Result.match(result, {
          onFailure: (error) =>
            Match.value(error).pipe(
              Match.tag("RepositoryFileReadError", (failure) => {
                expect(failure.file).toBe(
                  RepositoryRelativeFile.make("removed-after-index.md")
                );
              }),
              Match.orElse(() => expect.unreachable())
            ),
          onSuccess: () => expect.unreachable(),
        });
      })
  );
});
import { fileURLToPath } from "node:url";

import { Effect, FileSystem, Stream } from "effect";
import * as ChildProcess from "effect/process/ChildProcess";
import * as ChildProcessSpawner from "effect/process/ChildProcessSpawner";

const repositoryRoot = fileURLToPath(new URL("../..", import.meta.url));
const oxlint = fileURLToPath(
  new URL("../../node_modules/.bin/oxlint", import.meta.url)
);

/** Runs the repository's actual lint binary within the caller's test scope. */
export const lintFiles = Effect.fn("OxlintFixture.lintFiles")(function* (
  paths: readonly string[],
  extraArgs: readonly string[] = [],
  format: "json" | "unix" = "unix",
  configuration = "oxlint.config.ts"
) {
  const spawner = yield* ChildProcessSpawner.ChildProcessSpawner;
  const child = yield* spawner.spawn(
    ChildProcess.make(
      oxlint,
      [
        "-c",
        configuration,
        "--disable-nested-config",
        "--no-error-on-unmatched-pattern",
        `--format=${format}`,
        ...extraArgs,
        ...paths,
      ],
      { cwd: repositoryRoot, stderr: "pipe", stdout: "pipe" }
    )
  );
  const [exitCode, stdout, stderr] = yield* Effect.all(
    [
      child.exitCode,
      Stream.mkString(Stream.decodeText(child.stdout)),
      Stream.mkString(Stream.decodeText(child.stderr)),
    ],
    { concurrency: "unbounded" }
  );
  return { exitCode, output: `${stdout}${stderr}`, stdout };
});

/** Removes an exact configured fixture on success, failure or interruption. */
export const writeLintFixture = Effect.fn("OxlintFixture.writeLintFixture")(
  function* (path: string, source: string) {
    const fs = yield* FileSystem.FileSystem;
    yield* Effect.acquireRelease(Effect.succeed(path), (ownedPath) =>
      fs.remove(ownedPath, { force: true }).pipe(Effect.orDie)
    );
    yield* fs.writeFileString(path, source);
    return path;
  }
);

/** The platform owns unique temporary names and their scoped removal. */
export const writeTemporaryLintFixture = Effect.fn(
  "OxlintFixture.writeTemporaryLintFixture"
)(function* (source: string, extension = "ts", directory?: string) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* fs.makeTempFileScoped({
    directory,
    prefix: ".generated-taxkit-lint-",
    suffix: `.${extension}`,
  });
  yield* fs.writeFileString(path, source);
  return path;
});
